import requests

# ---------------------------------------------------------------------------
# History helpers (in-memory only — no file persistence)
# ---------------------------------------------------------------------------

_history: list[dict] = []


def clear_history() -> None:
    """Erase all in-memory question history."""
    global _history
    _history = []


def get_questions_list(limit: int | None = None) -> list[str]:
    """Return a flat list of past questions (newest first)."""
    questions = [entry.get("question", "") for entry in _history]
    return questions[:limit] if limit else questions


def get_history_summary(limit: int | None = None) -> dict:
    """Return a summary dict with the full history entries and a question list."""
    total = len(_history)
    history = _history[:limit] if limit else _history
    questions = [entry.get("question", "") for entry in history]
    return {
        "total": total,
        "returned": len(history),
        "questions": questions,
        "history": history,
    }

