def is_hp_question(question: str) -> bool:
    """Return True if the question is likely about Harry Potter.

    Matches both direct keywords (character/place/spell names) and indirect
    "manipulating" phrasings that describe something without naming it, such as
    "the one who cannot be named" (Voldemort).
    """
    q = question.lower()
    if any(kw in q for kw in HP_KEYWORDS):
        return True
    return any(phrase in q for phrase in HP_INDIRECT_PHRASES)


# ---------------------------------------------------------------------------
# Core OpenRouter helper
# ---------------------------------------------------------------------------

def _openrouter_chat(system: str, user: str, max_tokens: int = 400, timeout: int | None = None) -> str | None:
    if not OPENROUTER_API_KEY:
        return None
    try:
        resp = requests.post(
            OPENROUTER_API_URL,
            headers={
                "Authorization": f"Bearer {OPENROUTER_API_KEY}",
                "HTTP-Referer": OPENROUTER_SITE_URL,
                "X-Title": OPENROUTER_SITE_NAME,
                "Content-Type": "application/json",
            },
            json={
                "model": OPENROUTER_MODEL,
                "messages": [{"role": "system", "content": system}, {"role": "user", "content": user}],
                "temperature": 0.1,
                "max_tokens": max_tokens,
            },
            timeout=timeout or OPENROUTER_TRANSLATION_TIMEOUT,
        )
        resp.raise_for_status()
        choices = resp.json().get("choices", [])
        if not choices:
            return None
        content = choices[0].get("message", {}).get("content") or choices[0].get("text")
        return content.strip() if isinstance(content, str) and content.strip() else None
    except requests.RequestException:
        return None


# ---------------------------------------------------------------------------
# Language detection & translation
# ---------------------------------------------------------------------------

def is_likely_english(text: str) -> bool:
    if not text:
        return True
    if re.search(r"[\u0900-\u097F]", text):
        return False
    return bool(re.search(r"[A-Za-z]", text))


def translate_to_english(text: str) -> tuple[str, bool]:
    if not text or not text.strip() or is_likely_english(text):
        return text.strip() if text else text, False
    translated = _openrouter_chat(
        "Translate the following text into English. If already English, return unchanged. "
        "Respond only with the translated text.",
        text,
        max_tokens=200,
    )
    if not translated or translated.lower() == text.strip().lower():
        return text.strip(), False
    return translated, True


def translate_answer_to_original(answer_en: str, original_text: str) -> tuple[str, bool]:
    if not answer_en or not original_text:
        return answer_en, False
    translated = _openrouter_chat(
        "Translate the English answer into the same language as the example question below.\n"
        + HINDI_TRANSLATE_RULES + "\n\nExample question:\n" + original_text,
        answer_en,
    )
    return (translated, True) if translated else (answer_en, False)


def translate_text_to_language(text_en: str, target_lang: str) -> tuple[str, bool]:
    if not text_en or not target_lang:
        return text_en, False
    translated = _openrouter_chat(
        f"Translate the following English text into {target_lang}.\n" + HINDI_TRANSLATE_RULES,
        text_en,
    )
    return (translated, True) if translated else (text_en, False)


# ---------------------------------------------------------------------------
# AI answer functions
# ---------------------------------------------------------------------------

def ask_ai(question: str) -> str | None:
    """Harry Potter Q&A via OpenRouter."""
    return _openrouter_chat(get_system_prompt(), question.strip(), max_tokens=400, timeout=OPENROUTER_AI_TIMEOUT)


def ask_general_ai(question: str) -> str | None:
    """General-purpose AI answers for the help assistant chatbot."""
    return _openrouter_chat(
        get_general_assistant_prompt(),
        question.strip(),
        max_tokens=600,
        timeout=OPENROUTER_AI_TIMEOUT,
    )


# ---------------------------------------------------------------------------
# Public entry points
# ---------------------------------------------------------------------------

def process_ask(question: str) -> dict:
    """Harry Potter Q&A — off-topic questions get a static rejection, HP questions go to AI."""
    if not question or not question.strip():
        return {
            "question": question,
            "answer": "Please provide a question about Harry Potter.",
            "source": "validation",
        }

    translated_question, was_translated = translate_to_english(question)

    # Reject non-Harry Potter questions immediately
    if not is_hp_question(translated_question):
        return {
            "question": question,
            "translated_question": translated_question if was_translated else None,
            "answer": NOT_HP_RESPONSE,
            "source": "off_topic",
        }

    ai_answer = ask_ai(translated_question)
    answer = ai_answer or get_fallback_message(translated_question)
    source = "ai" if ai_answer else "fallback"

    result = {
        "question": question,
        "translated_question": translated_question if was_translated else None,
        "answer": answer,
        "source": source,
    }

    if was_translated and ai_answer:
        translated_back, ok = translate_answer_to_original(answer, question)
        if ok:
            result["original_answer_english"] = answer
            result["answer"] = translated_back
        result["language_translation"] = "translated to original language" if ok else "translated to English"

    return result


def process_help_chat(question: str) -> dict:
    """Help assistant: general AI answers for any topic EXCEPT Harry Potter.

    The Harry Potter assistant and the general Help Assistant are kept strictly
    separate — HP questions asked here are rejected, not answered.
    """
    if not question or not question.strip():
        return {
            "question": question,
            "answer": "Hi! Ask me anything — I'm here to help.",
            "source": "validation",
        }

    translated_question, was_translated = translate_to_english(question)

    # Reject Harry Potter questions — those belong to the dedicated HP assistant only.
    if is_hp_question(translated_question):
        return {
            "question": question,
            "translated_question": translated_question if was_translated else None,
            "answer": "",
            "source": "off_topic",
        }

    ai_answer = ask_general_ai(translated_question)
    answer = ai_answer or GENERAL_AI_FALLBACK
    source = "ai" if ai_answer else "fallback"

    result = {
        "question": question,
        "translated_question": translated_question if was_translated else None,
        "answer": answer,
        "source": source,
    }

    if was_translated and ai_answer:
        translated_back, ok = translate_answer_to_original(answer, question)
        if ok:
            result["original_answer_english"] = answer
            result["answer"] = translated_back

    return result
